namespace DiwaliGameplay {
public static class FinalPassVerification {
 public static bool IsRunning;
 public static string VenueFilter="";
 public static string ReportPath=>Path.GetFullPath("../Game_Plans/FinalPassVerification.json");
 static readonly List<object> rows=new List<object>();static int failures;static string scope;
 static NearFarInteractor hand;static GrabbableItem held;static Vector3 offset;static float floor;
 static VenueGame current;static DateTime started;static Vector3 proxyEye;
 static async Task Pause(int ms=120){int frame=Time.frameCount;await Task.Delay(ms);while(EditorApplication.isPlaying&&Time.frameCount<frame+2)await Task.Delay(20);}
 static void Save(string state){Directory.CreateDirectory(Path.GetDirectoryName(ReportPath));File.WriteAllText(ReportPath,Newtonsoft.Json.JsonConvert.SerializeObject(new{state,started,elapsedSeconds=(DateTime.UtcNow-started).TotalSeconds,failures,scope="Synthetic queued NearFar controller and XR UI presses; far casts limited to 3m. All selection/UI origins are at standing hand height, remote grab distances 0.65-3m. Carried movement is synthetic and does not establish physical headset reach. No headset or visual QA claim.",results=rows},Newtonsoft.Json.Formatting.Indented));}
 static void Check(string name,bool pass,string detail=""){if(!pass)failures++;rows.Add(new{venue=scope,name,pass,detail,status=current?current.status:"",hand=hand?hand.transform.position.ToString("F3"):"",held=held?held.itemId:"",proxyEye=proxyEye.ToString("F3")});Save("running");if(!pass)Debug.LogWarning("Final pass QA: "+scope+" / "+name+" / "+detail);}
 static async Task Until(Func<bool> predicate,int timeout=1800){var end=DateTime.UtcNow.AddMilliseconds(timeout);while(EditorApplication.isPlaying&&!predicate()&&DateTime.UtcNow<end)await Pause(60);}
 static Bounds Bounds(GrabbableItem item){var cols=item.grab.colliders.Where(c=>c&&c.enabled&&c.gameObject.activeInHierarchy).ToArray();if(cols.Length==0)return GameObjectUtility.BoundsOf(item.transform);var b=cols[0].bounds;foreach(var c in cols.Skip(1))b.Encapsulate(c.bounds);return b;}
 static void Pose(Vector3 position,Vector3 direction){hand.transform.SetPositionAndRotation(position,Quaternion.LookRotation(direction.normalized,Mathf.Abs(Vector3.Dot(direction.normalized,Vector3.up))>.98f?Vector3.forward:Vector3.up));var front=Vector3.ProjectOnPlane(direction,Vector3.up).normalized;if(front.sqrMagnitude<.1f)front=Vector3.forward;proxyEye=position-front*.3f;proxyEye.y=floor+1.6f;{var camera=Camera.main;if(camera){var rig=camera.transform.root;float yaw=Mathf.Atan2(front.x,front.z)*Mathf.Rad2Deg;rig.RotateAround(camera.transform.position,Vector3.up,Mathf.DeltaAngle(camera.transform.eulerAngles.y,yaw));rig.position+=proxyEye-camera.transform.position;}}}
 static async Task Release(){if(hand){hand.uiPressInput.QueueManualState(false,0);hand.selectInput.QueueManualState(false,0);}held=null;await Pause();}
 static async Task<bool> Grip(GrabbableItem item){await Release();if(!item||!item.grab||!item.grab.enabled){Check("grabbable enabled",false,item?item.itemId:"missing item");return false;}bool found=false;string lastTargets="";var target=Bounds(item).center;var directions=current is FireworksGame?new[]{Vector3.back,Vector3.right,Vector3.left,Vector3.forward,(Vector3.up+Vector3.back).normalized}:new[]{Vector3.forward,Vector3.back,Vector3.right,Vector3.left,(Vector3.up+Vector3.forward).normalized};foreach(var dir in directions){var origin=target+dir*1.05f;origin.y=Mathf.Clamp(origin.y,floor+.8f,floor+1.45f);if((target-origin).magnitude>3||(target-origin).magnitude<.65f)continue;Pose(origin,target-origin);await Pause(75);var valid=new List<IXRInteractable>();hand.GetValidTargets(valid);lastTargets=string.Join(",",valid.Select(v=>v.transform.name));if(valid.Contains(item.grab)){found=true;break;}}
 Check("3m NearFar targets "+item.itemId,found,"target="+target+",distance="+Vector3.Distance(target,hand.transform.position)+",valid="+lastTargets+",blockers="+string.Join(",",Physics.RaycastAll(hand.transform.position,(target-hand.transform.position).normalized,Vector3.Distance(target,hand.transform.position),~0,QueryTriggerInteraction.Ignore).OrderBy(h=>h.distance).Take(5).Select(h=>h.collider.name+"@"+h.distance.ToString("F2"))));if(!found)return false;hand.selectInput.QueueManualState(true,1);await Pause(240);Check("queued grip "+item.itemId,item.IsHeld);if(!item.IsHeld)return false;held=item;offset=item.transform.position-hand.transform.position;return true;}
 static async Task Move(Vector3 target){if(!held)return;var desired=target-offset;var start=hand.transform.position;for(int i=1;i<=4;i++){hand.transform.position=Vector3.Lerp(start,desired,i/4f);await Pause(35);}await Pause(80);offset=held.transform.position-hand.transform.position;for(int retry=0;retry<3&&held&&Vector3.Distance(held.transform.position,target)>.08f;retry++){hand.transform.position+=target-held.transform.position;await Pause(100);}if(held)offset=held.transform.position-hand.transform.position;}
 static async Task Drop(GrabbableItem item,Vector3 target){if(await Grip(item)){await Move(target);await Release();await Pause(400);}}
 static Button Button(VenueGame game,string name)=>game.GetComponentsInChildren<Button>(true).FirstOrDefault(b=>b.name==name);
 static async Task Click(VenueGame game,string name){await Release();await Pause(70);Canvas.ForceUpdateCanvases();var button=Button(game,name);bool available=button&&button.gameObject.activeInHierarchy&&button.interactable;Check("visible UI "+name,available);if(!available)return;var canvas=button.GetComponentInParent<Canvas>();var rect=button.GetComponent<RectTransform>();var center=rect.TransformPoint(rect.rect.center);var origin=center-canvas.transform.forward*1.2f;origin.y=Mathf.Clamp(origin.y,floor+.8f,floor+1.45f);Pose(origin,center-origin);await Pause(160);var hits=new List<RaycastResult>();var ray=new TrackedDeviceEventData(EventSystem.current){rayPoints=new List<Vector3>{origin,center+canvas.transform.forward*.05f},layerMask=~0};canvas.GetComponent<TrackedDeviceGraphicRaycaster>().Raycast(ray,hits);Check("tracked ray "+name,hits.Any(h=>h.gameObject==button.gameObject),"hits="+string.Join(",",hits.Select(h=>h.gameObject.name)));int clicks=0;UnityEngine.Events.UnityAction counter=()=>clicks++;button.onClick.AddListener(counter);hand.uiPressInput.QueueManualState(true,1);await Pause(160);hand.uiPressInput.QueueManualState(false,0);await Pause(180);button.onClick.RemoveListener(counter);Check("queued UI dispatch "+name,clicks==1,"clicks="+clicks);}
 static async Task Slider(VenueGame game,string label,float normalized){await Release();await Pause(300);Canvas.ForceUpdateCanvases();var slider=game.GetComponentsInChildren<Slider>(true).FirstOrDefault(s=>s.name==label+" slider"&&s.gameObject.activeInHierarchy&&s.interactable);Check("visible slider "+label,slider);if(!slider)return;var rect=slider.GetComponent<RectTransform>();var canvas=slider.GetComponentInParent<Canvas>();var a=rect.TransformPoint(new Vector3(Mathf.Lerp(rect.rect.xMin,rect.rect.xMax,.1f),rect.rect.center.y,0));var b=rect.TransformPoint(new Vector3(Mathf.Lerp(rect.rect.xMin,rect.rect.xMax,normalized),rect.rect.center.y,0));var origin=a-canvas.transform.forward*1.1f;origin.y=Mathf.Clamp(origin.y,floor+.8f,floor+1.45f);Pose(origin,a-origin);await Pause(140);hand.uiPressInput.QueueManualState(true,1);await Pause(120);Pose(origin,b-origin);await Pause(240);hand.uiPressInput.QueueManualState(false,0);await Pause(140);var expected=Mathf.Lerp(slider.minValue,slider.maxValue,normalized);Check("queued slider drag "+label,Mathf.Abs(slider.value-expected)<.15f,"value="+slider.value+",expected="+expected);}
 static async Task Venue(VenueGame game,Func<Task> test){current=game;scope=game?game.GetType().Name:"missing venue";floor=game?game.transform.position.y:0;try{Check("runtime venue",game);if(!game)return;game.ResetGame();await Pause();Check("panel exists",game.GetComponentInChildren<VenuePanel>());await Click(game,"How To Play");Check("help canvas opens",Button(game,"Close")&&Button(game,"Close").gameObject.activeInHierarchy);var next=Button(game,"Next");if(next&&next.gameObject.activeInHierarchy&&next.interactable){await Click(game,"Next");Check("help Previous enabled",Button(game,"Previous")&&Button(game,"Previous").interactable);await Click(game,"Previous");}await Click(game,"Close");Check("main canvas resumes",game.GetComponentInChildren<VenuePanel>().GetComponent<Canvas>().enabled);await test();}catch(Exception error){Check("exception",false,error.ToString());}finally{await Release();if(game){game.ResetGame();await Pause();Check("reset clears progress",!game.begun&&!game.completed&&game.credited.Count==0);if(game is SweetGame sweet)Check("reset clears sweet contents and authorization",sweet.selected.Count==0&&!sweet.authorized&&!sweet.docked&&!sweet.confirmed);if(game is FireworksGame fireworks)Check("reset unloads fireworks",fireworks.stage==0&&!fireworks.rocketLoaded&&!fireworks.fountainLoaded&&!fireworks.spinnerLoaded&&!fireworks.rocketEffect.isPlaying&&!fireworks.fountainEffect.isPlaying&&!fireworks.spinnerEffect.isPlaying);if(game is RoutingGame routing)Check("reset clears circuit",routing.placed.All(p=>!p)&&!routing.tested&&!routing.brightnessChosen);if(game is RangoliGame rangoli)Check("reset releases all matched pieces",rangoli.sockets.All(p=>!p.occupant)&&rangoli.pieces.All(p=>p.grab.enabled));if(game is DiyaGame diya)Check("reset clears diya flame and route",!diya.lit&&!diya.clean&&!diya.transferred&&diya.nextCheckpoint==0&&!diya.carriedFlame.enabled);}}}
 [MenuItem("Diwali/Gameplay/Run final pass verification")]
 public static async void Run(){if(IsRunning||!EditorApplication.isPlaying)return;IsRunning=true;rows.Clear();failures=0;started=DateTime.UtcNow;scope="setup";GameObject controller=null;var camera=Camera.main;var rig=camera?camera.transform.root:null;var originalPosition=rig?rig.position:Vector3.zero;var originalRotation=rig?rig.rotation:Quaternion.identity;try{
 controller=new GameObject("Final pass queued controller");controller.AddComponent<Rigidbody>().isKinematic=true;var collider=controller.AddComponent<SphereCollider>();collider.isTrigger=true;collider.radius=.045f;hand=controller.AddComponent<NearFarInteractor>();hand.interactionManager=UnityEngine.Object.FindFirstObjectByType<XRInteractionManager>();hand.enableNearCasting=true;hand.enableUIInteraction=true;hand.selectInput.inputSourceMode=XRInputButtonReader.InputSourceMode.ManualValue;hand.uiPressInput.inputSourceMode=XRInputButtonReader.InputSourceMode.ManualValue;var attach=hand.interactionAttachController as InteractionAttachController;attach.transformToFollow=controller.transform;attach.useMomentum=false;attach.useDistanceBasedVelocityScaling=false;attach.useManipulationInput=false;if(hand.farInteractionCaster is CurveInteractionCaster cast){cast.hitDetectionType=CurveInteractionCaster.HitDetectionType.Raycast;cast.castDistance=3;}await Pause(250);Check("XR UI input module",UnityEngine.Object.FindFirstObjectByType<XRUIInputModule>());Check("event system",EventSystem.current);
 if(string.IsNullOrEmpty(VenueFilter)||VenueFilter.Contains("FireworksGame"))await Venue(UnityEngine.Object.FindFirstObjectByType<FireworksGame>(),Fireworks);
 if(string.IsNullOrEmpty(VenueFilter)||VenueFilter.Contains("RangoliGame"))await Venue(UnityEngine.Object.FindFirstObjectByType<RangoliGame>(),Rangoli);
 if(string.IsNullOrEmpty(VenueFilter)||VenueFilter.Contains("RoutingGame"))await Venue(UnityEngine.Object.FindFirstObjectByType<RoutingGame>(),Routing);
 if(string.IsNullOrEmpty(VenueFilter)||VenueFilter.Contains("SweetGame"))await Venue(UnityEngine.Object.FindFirstObjectByType<SweetGame>(),Sweet);
 if(string.IsNullOrEmpty(VenueFilter)||VenueFilter.Contains("DiyaGame"))await Venue(UnityEngine.Object.FindFirstObjectByType<DiyaGame>(),Diya);
 }catch(Exception error){Check("harness exception",false,error.ToString());}finally{await Release();foreach(var game in UnityEngine.Object.FindObjectsByType<VenueGame>(FindObjectsSortMode.None))game.ResetGame();if(rig){rig.SetPositionAndRotation(originalPosition,originalRotation);}if(controller)UnityEngine.Object.Destroy(controller);hand=null;held=null;IsRunning=false;VenueFilter="";Save(failures==0?"passed":"failed");Debug.Log("Final pass verification: "+failures+" failures. "+ReportPath);}}
 static async Task Rangoli(){var g=(RangoliGame)current;await Click(g,"Begin Rangoli");g.Celebrate();Check("premature finish rejected",!g.completed);await Click(g,"Magenta / gold");Check("palette chosen",g.palette==1);Check("wrong shape rejected",!g.sockets[0].TryAccept(g.pieces[1]));for(int i=0;i<g.pieces.Length;i++){await Drop(g.pieces[i],g.sockets[i].transform.position+Vector3.up*.15f);Check("matched piece "+i,g.sockets[i].occupant==g.pieces[i]);Check("placed piece locked "+i,!g.pieces[i].grab.enabled);}var displayPanel=g.GetComponentInChildren<VenuePanel>();Check("display menu at standing height",displayPanel.transform.position.y>=1.1f&&displayPanel.transform.position.y<=1.75f,"height="+displayPanel.transform.position.y);var before=g.sun.rotation;await Click(g,"Rotate Sun");await Pause(700);Check("sun rotates 45 degrees",Mathf.Abs(Quaternion.Angle(before,g.sun.rotation)-45)<2);await Slider(g,"Pavilion brightness",.8f);Check("brightness changes pavilion",g.brightness>.7f);await Click(g,"Celebrate");Check("completed",g.completed);}
 static async Task Routing(){var g=(RoutingGame)current;await Click(g,"Begin Lighting");g.TestLights();Check("incomplete route blocked",!g.tested);for(int i=0;i<g.pieces.Length;i++){await Drop(g.pieces[i],g.sockets[i].transform.position+Vector3.up*.12f);Check("route piece fitted "+i,g.placed[i]);if(i>0){for(int j=0;j<4&&!g.Aligned(i-1);j++)await Click(g,new[]{"Rotate elbow ↻","Rotate T-junction ↻","Rotate straight ↻"}[i-1]);Check("connector aligned "+i,g.Aligned(i-1));}}await Click(g,"Test Lights");await Until(()=>g.tested,6000);Check("test pulse reaches garden",g.tested);await Click(g,"Change garden brightness");Check("garden brightness chosen",g.brightnessChosen);await Click(g,"Confirm brightness");Check("completed",g.completed);Check("garden lamps lit",g.destinations.All(l=>l.intensity>0));}
 static async Task Plunge(FireworksGame g,int stage){if(await Grip(g.plunger)){var p=hand.transform.position;hand.transform.position=p-Vector3.up*.04f;await Pause(180);Check("short plunger travel does not activate",g.stage==stage);hand.transform.position=p-Vector3.up*.125f;await Until(()=>g.stage!=stage,stage==0?2600:500);Check("physical plunger advances stage "+stage,g.stage==stage+1,"progress="+g.PlungerProgress);}await Release();}
 static async Task Fireworks(){var g=(FireworksGame)current;await Click(g,"Begin Light Show");Check("independent finale initially blocked",!g.completed);Check("staging separated",Vector3.Distance(g.rocket.transform.position,g.rocketSocket.position)>.7f);Check("unheld plunger call blocked",!g.Press(0));if(await Grip(g.rocket)){var relative=hand.transform.InverseTransformPoint(GameObjectUtility.BoundsOf(g.rocket.transform).center);Check("rocket hand clearance",relative.z>.35f&&relative.z<=1.2f,"relative="+relative);Check("rocket collider clears controller",g.rocket.grab.colliders.Where(c=>c&&c.enabled).Min(c=>Vector3.Distance(c.ClosestPoint(hand.transform.position),hand.transform.position))>.08f);Check("rocket upright carrying pose",Vector3.Dot(g.rocket.transform.TransformDirection(g.rocketLocalLaunchAxis).normalized,Vector3.up)>.95f);var scale=g.rocket.transform.lossyScale;await Move(g.rocket.transform.position+Vector3.right*.35f);Check("carried rocket scale stable",Vector3.Distance(scale,g.rocket.transform.lossyScale)<.005f);await Move(g.rocketSocket.position+Vector3.up*.2f);await Release();await Pause(220);}Check("rocket loads on release",g.rocketLoaded);
 await Slider(g,"Tilt rocket up / down",.7f);await Slider(g,"Target board height",.5f);var board=g.GetComponent<FireworksTargetBoard>();float chosenAim=-1,chosenHeight=0;for(int h=0;h<=10&&chosenAim<0;h++){board.SetHeight(h/10f);for(int a=0;a<=20;a++){g.AdjustAim(a/20f);if(g.TargetAligned()){chosenAim=a/20f;chosenHeight=h/10f;break;}}}Check("reachable target path exists",chosenAim>=0);if(chosenAim<0)return;
 // Geometry search chooses settings; the accepted setting is then entered through tracked UI.
 await Slider(g,"Tilt rocket up / down",Mathf.Clamp(chosenAim,.02f,.98f));await Slider(g,"Target board height",Mathf.Clamp(chosenHeight,.02f,.98f));Check("tracked controls align rocket",g.TargetAligned());await Plunge(g,0);if(g.stage!=1)return;await Drop(g.fountain,g.fountainSocket.position+Vector3.up*.2f);Check("fountain loaded",g.fountainLoaded);var lift=g.lift.position.y;await Slider(g,"Fountain lift height",.8f);await Pause(650);Check("lift visibly raises",g.lift.position.y>lift+.05f);await Plunge(g,1);await Drop(g.spinner,g.spinnerSocket.position+Vector3.up*.2f);Check("spinner loaded",g.spinnerLoaded);await Slider(g,"Spinner speed",.8f);await Plunge(g,2);var rotation=g.spinnerPivot.rotation;await Pause(450);Check("spinner rotates",Quaternion.Angle(rotation,g.spinnerPivot.rotation)>5);await Click(g,"Finale");Check("finale without other venue completion",g.completed);await Pause(2500);Check("all three particle loops remain playing",g.rocketEffect.isPlaying&&g.fountainEffect.isPlaying&&g.spinnerEffect.isPlaying);var rewards=UnityEngine.Object.FindFirstObjectByType<FestivalRewards>();Check("central finale runs",rewards&&rewards.CentralDisplayRunning);}
 static async Task Sweet(){var g=(SweetGame)current;await Click(g,"Make a Gift Basket");Check("early card rejected",!g.AuthorizeCard());await Click(g,"Open Cabinet");await Pause(700);var first=g.glass.Select(t=>t.position).ToArray();await Click(g,"Switch open side");await Pause(700);Check("cabinet switching moves panels",g.glass.Where((t,i)=>Vector3.Distance(t.position,first[i])>.1f).Any());Check("cabinet glass remains separated",!GameObjectUtility.BoundsOf(g.glass[0]).Intersects(GameObjectUtility.BoundsOf(g.glass[1])));await Click(g,"Switch open side");await Pause(650);var upper=g.baskets.OrderByDescending(b=>Bounds(b).center.y).First();await Drop(upper,g.rest.position+Vector3.up*.15f);Check("upper basket settles at rest",g.basket==upper&&g.basketReady);var lower=g.baskets.First(b=>b!=upper);await Drop(lower,g.rest.position+Vector3.up*.15f);Check("empty basket can swap",g.basket==lower&&g.basketReady);await Click(g,"Switch open side");await Pause(700);var choices=g.sweets.GroupBy(s=>s.itemId).Select(s=>s.First()).Take(3).ToList();choices.Add(g.sweets.First(s=>!choices.Contains(s)));for(int i=0;i<4;i++){await Drop(choices[i],g.basket.transform.position+Vector3.up*.2f);Check("sweet packed "+i,g.selected.Contains(choices[i]),"count="+g.selected.Count);}Check("four mixed sweets accepted",g.selected.Count==4);if(g.selected.Count!=4)return;var remove=choices[0];if(await Grip(remove)){Check("grip removes packed sweet",g.selected.Count==3);var target=g.ShelfReturnTarget(remove);Check("original shelf return target",target);if(target)await Move(target.position+Vector3.right*.12f);await Release();await Pause(220);Check("sweet returns to original shelf",target&&Vector3.Distance(remove.transform.position,target.position)<.05f);Check("returned sweet leaves contents",!g.selected.Contains(remove));}await Drop(remove,g.basket.transform.position+Vector3.up*.2f);Check("returned sweet can be repacked",g.selected.Count==4);await Drop(g.basket,g.checkout.position+Vector3.up*.15f);Check("basket docks at checkout",g.docked);if(await Grip(g.card)){await Move(g.cardReader.position);await Until(()=>g.authorized);Check("held card authorizes checkout",g.authorized);Check("physical monitor shows card accepted",FinishTodayVerification.MonitorShows("ACCEPTED"));FinishTodayVerification.CaptureCheckoutStatus("Card-Accepted");await Release();}if(await Grip(remove)){Check("changing contents invalidates card",!g.authorized&&g.selected.Count==3);await Move(g.ShelfReturnTarget(remove).position);await Release();await Pause(180);}await Drop(remove,g.basket.transform.position+Vector3.up*.2f);Check("swap restores four sweets",g.selected.Count==4);if(await Grip(g.card)){await Move(g.cardReader.position+g.workspaceForward*.9f);await Pause(180);await Move(g.cardReader.position);await Until(()=>g.authorized);Check("card can authorize changed gift",g.authorized);await Release();}await Click(g,"Confirm Gift");Check("gift completes at checkout",g.completed&&g.confirmed);Check("physical monitor shows gift ready",FinishTodayVerification.MonitorShows("GIFT READY"));FinishTodayVerification.CaptureCheckoutStatus("Gift-Ready");Check("packed sweets lock after confirmation",g.selected.All(s=>!s.grab.enabled));var rewards=UnityEngine.Object.FindFirstObjectByType<FestivalRewards>();Check("checkout sharing celebration activates",rewards&&rewards.SweetsShared&&rewards.SweetCelebrationActive);Check("no central sweet gift plinth",!GameObjectUtility.FindExact("Sweet sharing plinth"));await Pause(4200);Check("checkout celebration ends",rewards&&!rewards.SweetCelebrationActive);}
 static async Task Diya(){var g=(DiyaGame)current;var floorArt=GameObjectUtility.FindUnder(GameObjectUtility.FindExact("Diya - Approved Warm Palette"),"Plane.002").GetComponent<Renderer>();Check("progressive path preserves authored atlas",floorArt.sharedMaterials[1].GetTexture("_BaseMap")==floorArt.sharedMaterials[0].GetTexture("_BaseMap"));g.OpenChest();Check("locked chest rejects opening",g.Step==0);await Click(g,"Open Drawer");await Pause(800);Check("drawer action advances",g.Step==1);if(await Grip(g.scroll)){await Pause(180);Check("scroll inspection guide appears",g.inspected&&g.guide.activeInHierarchy);await Move(g.scrollRest.position+Vector3.up*.15f);await Release();await Pause(180);}Check("scroll returned",g.Step==2&&!g.guide.activeInHierarchy);await Drop(g.pot,g.potRest.position+Vector3.up*.15f);Check("pot reveals key",g.Step==3);await Drop(g.key,g.keySocket.position+Vector3.up*.1f);Check("key inserts without opening chest",g.keyInserted&&g.Step==3);var keyBefore=g.key.transform.rotation;await Click(g,"Turn Inserted Key");await Until(()=>g.Step==4);Check("key turns around inserted shaft",g.Step==4&&Mathf.Abs(Quaternion.Angle(keyBefore,g.key.transform.rotation)-60)<2);await Click(g,"Open Chest");await Pause(1250);Check("chest reveals feather",g.Step==5&&g.feather.grab.enabled);if(await Grip(g.feather)){await Move(g.diya.transform.position);for(int i=0;i<12&&!g.clean;i++)await Move(g.diya.transform.position+Vector3.right*(i%2==0?.1f:-.1f));Check("brushing cleans diya",g.clean);await Move(g.featherRest.position+Vector3.right*.7f);await Release();await Pause(180);}Check("feather accepts forgiving return",g.Step==6);await Click(g,"Reveal Starter Flame");await Pause(1000);Check("starter flame revealed",g.Step==7&&g.starterFlame.enabled);if(await Grip(g.diya)){await Move(g.diya.transform.position+g.starter.position-g.carriedFlame.transform.position);await Until(()=>g.lit);Check("starter lights held diya",g.lit&&g.Step==8);Check("out of order checkpoint rejected",!g.TryCheckpoint(2,true,true));for(int i=0;i<3;i++){var camera=Camera.main;if(camera){var delta=g.checkpoints[i].position-camera.transform.position;delta.y=0;camera.transform.root.position+=delta;}var position=g.diya.transform.position;position.x=g.checkpoints[i].position.x;position.z=g.checkpoints[i].position.z;await Move(position);await Until(()=>g.nextCheckpoint>=i+1,600);Check("ordered floor route "+i,g.nextCheckpoint>=i+1);}var pathBlock=new MaterialPropertyBlock();floorArt.GetPropertyBlock(pathBlock,1);Check("walking records progressive floor illumination",pathBlock.GetInt("_VisitedCount")>=3,"visited="+pathBlock.GetInt("_VisitedCount"));await Move(g.diya.transform.position+g.destination.position-g.carriedFlame.transform.position);await Until(()=>g.transferred);Check("central flame receives transfer",g.transferred);await Move(g.diyaRest.position+Vector3.up*.2f);await Release();await Pause(220);}Check("diya delivery completes",g.completed);}
}
